# CekRingkas Component Scanner V1.0 - Windows PowerShell 5.1
$ErrorActionPreference='SilentlyContinue'
Add-Type -AssemblyName System.Windows.Forms
$desktop=[Environment]::GetFolderPath('Desktop'); if(!(Test-Path $desktop)){$desktop=$env:TEMP}
$stamp=Get-Date -Format 'yyyyMMdd_HHmmss'
$sys=Get-CimInstance Win32_ComputerSystem
$bios=Get-CimInstance Win32_BIOS
$board=Get-CimInstance Win32_BaseBoard
$cpu=Get-CimInstance Win32_Processor
$os=Get-CimInstance Win32_OperatingSystem
$ram=Get-CimInstance Win32_PhysicalMemory
$disks=Get-CimInstance Win32_DiskDrive
$battery=Get-CimInstance Win32_Battery
$video=Get-CimInstance Win32_VideoController
$net=Get-CimInstance Win32_NetworkAdapter | Where-Object {$_.PhysicalAdapter -eq $true}
$audio=Get-CimInstance Win32_SoundDevice
$pnp=Get-CimInstance Win32_PnPEntity | Where-Object {$_.ConfigManagerErrorCode -and $_.ConfigManagerErrorCode -ne 0}
$physical=@(Get-CimInstance Win32_PhysicalMemoryArray)
$slotCount=0; foreach($p in $physical){$slotCount += [int]$p.MemoryDevices}
$ramTotal=[math]::Round((($ram | Measure-Object Capacity -Sum).Sum)/1GB,2)
$diskRows=foreach($d in $disks){[pscustomobject]@{Model=$d.Model; Manufacturer=$d.Manufacturer; SerialNumber=$d.SerialNumber; InterfaceType=$d.InterfaceType; MediaType=$d.MediaType; SizeGB=[math]::Round($d.Size/1GB,2); Status=$d.Status; Firmware=$d.FirmwareRevision}}
$ramRows=foreach($m in $ram){[pscustomobject]@{BankLabel=$m.BankLabel; DeviceLocator=$m.DeviceLocator; CapacityGB=[math]::Round($m.Capacity/1GB,2); Manufacturer=$m.Manufacturer; PartNumber=([string]$m.PartNumber).Trim(); SerialNumber=$m.SerialNumber; MemoryType=$m.MemoryType; SMBIOSMemoryType=$m.SMBIOSMemoryType; SpeedMHz=$m.Speed; ConfiguredClockSpeedMHz=$m.ConfiguredClockSpeed; FormFactor=$m.FormFactor}}
$components=@(
 [pscustomobject]@{Komponen='Motherboard'; Deteksi=if($board){"$($board.Manufacturer) $($board.Product)"}else{'Tidak dilaporkan firmware'}; Detail="Serial=$($board.SerialNumber); Versi=$($board.Version)"; Status=if($board){'TERDETEKSI'}else{'VERIFIKASI'}},
 [pscustomobject]@{Komponen='CPU'; Deteksi=($cpu.Name -join '; '); Detail=(($cpu | ForEach-Object {"Core=$($_.NumberOfCores), Thread=$($_.NumberOfLogicalProcessors), MaxMHz=$($_.MaxClockSpeed)"}) -join '; '); Status=if($cpu){'TERDETEKSI'}else{'VERIFIKASI'}},
 [pscustomobject]@{Komponen='RAM'; Deteksi="$ramTotal GB; modul terlapor=$($ram.Count); slot maksimum firmware=$slotCount"; Detail=(($ramRows | ForEach-Object {"$($_.DeviceLocator) $($_.CapacityGB)GB $($_.Manufacturer) $($_.PartNumber) $($_.SpeedMHz)MHz"}) -join ' | '); Status=if($ram.Count){'TERDETEKSI'}else{'VERIFIKASI'}},
 [pscustomobject]@{Komponen='Storage'; Deteksi=(($diskRows | ForEach-Object {"$($_.Model) $($_.SizeGB)GB [$($_.Status)]"}) -join '; '); Detail='SMART detail bergantung dukungan driver/vendor; Status WMI bukan hasil SMART penuh.'; Status=if($disks){'TERDETEKSI'}else{'VERIFIKASI'}},
 [pscustomobject]@{Komponen='GPU'; Deteksi=($video.Name -join '; '); Detail=(($video | ForEach-Object {"Driver=$($_.DriverVersion); Resolusi=$($_.CurrentHorizontalResolution)x$($_.CurrentVerticalResolution); VRAM-report=$([math]::Round($_.AdapterRAM/1GB,2))GB"}) -join '; '); Status=if($video){'TERDETEKSI'}else{'VERIFIKASI'}},
 [pscustomobject]@{Komponen='Baterai'; Deteksi=if($battery){($battery.Name -join '; ')}else{'Tidak dilaporkan melalui WMI'}; Detail=(($battery | ForEach-Object {"Status=$($_.BatteryStatus); DesignVoltage=$($_.DesignVoltage); EstimatedCharge=$($_.EstimatedChargeRemaining)%"}) -join '; '); Status=if($battery){'TERDETEKSI'}else{'TIDAK DILAPORKAN'}},
 [pscustomobject]@{Komponen='Wi-Fi / Network'; Deteksi=(($net | ForEach-Object {$_.Name}) -join '; '); Detail=(($net | ForEach-Object {"Status=$($_.NetConnectionStatus); MAC=$($_.MACAddress); PNP=$($_.PNPDeviceID)"}) -join ' | '); Status=if($net){'TERDETEKSI'}else{'VERIFIKASI'}},
 [pscustomobject]@{Komponen='Audio'; Deteksi=(($audio | ForEach-Object {$_.Name}) -join '; '); Detail='Deteksi nama tidak membuktikan speaker/mikrofon bekerja secara fisik.'; Status=if($audio){'TERDETEKSI'}else{'VERIFIKASI'}},
 [pscustomobject]@{Komponen='Webcam'; Deteksi=((Get-CimInstance Win32_PnPEntity | Where-Object {$_.Name -match 'camera|webcam|imaging'} | ForEach-Object {$_.Name}) -join '; '); Detail='Harus dibuktikan dengan membuka aplikasi kamera.'; Status=if(Get-CimInstance Win32_PnPEntity | Where-Object {$_.Name -match 'camera|webcam|imaging'}){'TERDETEKSI'}else{'VERIFIKASI'}},
 [pscustomobject]@{Komponen='Device / Driver error'; Deteksi="$($pnp.Count) perangkat melaporkan ConfigManagerErrorCode non-zero"; Detail=(($pnp | Select-Object -First 30 | ForEach-Object {"$($_.Name) [Code $($_.ConfigManagerErrorCode)]"}) -join '; '); Status=if($pnp.Count){'PERLU DICEK'}else{'TIDAK ADA ERROR YANG DILAPORKAN'}}
)
$report=[pscustomobject]@{WaktuScan=(Get-Date).ToString('yyyy-MM-dd HH:mm:ss');ComputerName=$env:COMPUTERNAME;Manufacturer=$sys.Manufacturer;Model=$sys.Model;SystemSerial=$bios.SerialNumber;BIOSVersion=$bios.SMBIOSBIOSVersion;OS=$os.Caption;OSBuild=$os.BuildNumber;Motherboard=$board;CPU=$cpu;RAM=$ramRows;RAMTotalGB=$ramTotal;RAMSlotCountFirmware=$slotCount;Disks=$diskRows;Battery=$battery;GPU=$video;NetworkAdapters=$net;AudioDevices=$audio;PnPErrors=$pnp;Summary=$components}
$jsonPath=Join-Path $desktop "CekRingkas_ComponentScan_$stamp.json"
$htmlPath=Join-Path $desktop "CekRingkas_ComponentScan_$stamp.html"
$report | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $jsonPath -Encoding UTF8
function E($x){[System.Net.WebUtility]::HtmlEncode([string]$x)}
$rows=foreach($c in $components){$cls=if($c.Status -match 'TERDETEKSI|TIDAK ADA ERROR'){'ok'}elseif($c.Status -match 'PERLU|VERIFIKASI'){'warn'}else{'muted'};"<tr><td>$(E $c.Komponen)</td><td>$(E $c.PSObject.Properties['Deteksi'].Value)</td><td class='$cls'>$(E $c.Status)</td><td>$(E $c.Detail)</td></tr>"}
$ramTable=foreach($m in $ramRows){"<tr><td>$(E $m.DeviceLocator)</td><td>$(E $m.BankLabel)</td><td>$($m.CapacityGB) GB</td><td>$(E $m.Manufacturer)</td><td>$(E $m.PartNumber)</td><td>$(E $m.SerialNumber)</td><td>$(E $m.SMBIOSMemoryType)</td><td>$($m.SpeedMHz)</td><td>$($m.ConfiguredClockSpeedMHz)</td></tr>"}
$diskTable=foreach($d in $diskRows){"<tr><td>$(E $d.Model)</td><td>$($d.SizeGB) GB</td><td>$(E $d.InterfaceType)</td><td>$(E $d.MediaType)</td><td>$(E $d.Status)</td><td>$(E $d.SerialNumber)</td></tr>"}
$html=@"
<!doctype html><html lang='id'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>CekRingkas Component Scanner</title><style>body{font-family:Segoe UI,Arial;background:#f3f6fa;color:#1f2937;margin:0;padding:24px}.wrap{max-width:1250px;margin:auto;background:white;padding:24px;border-radius:14px}h1,h2{color:#174f78}table{width:100%;border-collapse:collapse;margin:12px 0 26px}th,td{border:1px solid #dbe2ea;padding:8px;text-align:left;vertical-align:top;font-size:12px;overflow-wrap:anywhere}th{background:#eaf1f7}.ok{color:#137333;font-weight:700}.warn{color:#946200;font-weight:700}.muted{color:#667085}.note{background:#fff4d6;padding:12px;border-left:4px solid #e6a700}.layout{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{border:1px solid #dbe2ea;border-radius:10px;padding:12px}.board{background:#203b32;border:5px solid #50695f;border-radius:16px;padding:18px;display:grid;grid-template-columns:1fr 1fr;gap:12px;min-height:240px;color:white}.part{border:2px solid #a7c7b7;background:#2f5749;border-radius:8px;padding:10px;text-align:center;font-size:12px}.part small{display:block;color:#c9e4d8;margin-top:4px}.caption{font-size:12px;color:#667085}@media(max-width:700px){.layout{grid-template-columns:1fr}}@media print{body{padding:0;background:white}.wrap{padding:0}.card,.board{break-inside:avoid}}</style></head><body><div class='wrap'><h1>CEKRINGKAS — LAPORAN SCANNER KOMPONEN</h1><p><b>Perangkat:</b> $(E "$($sys.Manufacturer) $($sys.Model)") &nbsp; <b>Serial:</b> $(E $bios.SerialNumber)<br><b>Motherboard:</b> $(E "$($board.Manufacturer) $($board.Product)") &nbsp; <b>BIOS:</b> $(E $bios.SMBIOSBIOSVersion)<br><b>Windows:</b> $(E $os.Caption) (build $(E $os.BuildNumber))<br><b>Waktu scan:</b> $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')</p><div class='note'><b>Batasan penting:</b> gambar motherboard di bawah adalah diagram ilustratif generik, bukan foto motherboard model laptop ini. PowerShell membaca data yang dilaporkan firmware/driver; tidak dapat memastikan jalur putus, short circuit, korosi, IC rusak, konektor longgar, atau mengukur SMART penuh di semua SSD. Konfirmasi dengan pemeriksaan fisik dan alat ukur.</div>
<h2>Peta komponen (ilustrasi generik)</h2><div class='layout'><div class='card'><div class='board'><div class='part'>CPU / GPU<small>Posisi dan bentuk bergantung model</small></div><div class='part'>RAM / Slot RAM<small>Onboard atau SO-DIMM</small></div><div class='part'>Chipset / PCH<small>Jika terpisah pada desain</small></div><div class='part'>M.2 SSD / SATA<small>Lokasi konektor bervariasi</small></div><div class='part'>Wi-Fi / WLAN<small>Modul M.2 atau onboard</small></div><div class='part'>BIOS / EC<small>Firmware motherboard</small></div></div><p class='caption'>Skema hanya untuk orientasi teknisi. Tata letak aktual perlu dicocokkan dengan service manual atau foto motherboard dari model yang tepat.</p></div><div class='card'><h3>Identitas papan</h3><p><b>Manufacturer:</b> $(E $board.Manufacturer)<br><b>Product:</b> $(E $board.Product)<br><b>Serial:</b> $(E $board.SerialNumber)<br><b>Version:</b> $(E $board.Version)</p><h3>Ringkasan cepat</h3><p>RAM: <b>$ramTotal GB</b> terdeteksi, modul: <b>$($ram.Count)</b>, slot maksimum yang dilaporkan firmware: <b>$slotCount</b>.</p><p>Perangkat PnP yang melaporkan error: <b>$($pnp.Count)</b>.</p></div></div>
<h2>Hasil deteksi komponen</h2><table><thead><tr><th>Komponen</th><th>Deteksi</th><th>Status</th><th>Detail / catatan</th></tr></thead><tbody>$($rows -join "`n")</tbody></table>
<h2>Detail RAM per modul</h2><table><thead><tr><th>Slot/Device Locator</th><th>Bank</th><th>Kapasitas</th><th>Brand</th><th>Part number</th><th>Serial</th><th>SMBIOS type</th><th>Speed</th><th>Configured speed</th></tr></thead><tbody>$($ramTable -join "`n")</tbody></table>
<h2>Detail storage</h2><table><thead><tr><th>Model</th><th>Kapasitas</th><th>Interface</th><th>Media</th><th>Status WMI</th><th>Serial</th></tr></thead><tbody>$($diskTable -join "`n")</tbody></table><p class='caption'>Laporan dibuat otomatis. Kolom yang kosong berarti Windows/firmware tidak memberikan nilai yang dapat dibaca, bukan berarti komponen pasti tidak ada.</p><button onclick='window.print()'>Cetak / Simpan PDF</button></div></body></html>
"@
[IO.File]::WriteAllText($htmlPath,$html,[Text.Encoding]::UTF8)
Start-Process $htmlPath
[void][System.Windows.Forms.MessageBox]::Show("Scanner selesai.`r`n`r`nHTML: $htmlPath`r`nJSON: $jsonPath`r`n`r`nDiagram motherboard bersifat ilustratif; bukan pemetaan PCB aktual.",'CekRingkas Component Scanner',[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Information)
